      "raw_content": "카페홈\n좌담회/설문/주부알바\n가입\n검색\n메뉴\n▶좌담회 신청하기(당일 현금지급)\n앱 열기\n공지\n▶9/9~11]최근6개월내 피부과 미용시술경험자 또는 최근2년내 피부과 미용시술 미경험자 좌담회/ 만30-49세 여성(전업주부 또는 풀타임 회사원)\n본문 기타 기능\n하늘\n카페매니저\n채팅\n작성일\n2026.09.02. 16:52\n조회 46\n▶9/9~11]최근6개월내 피부과 미용시술경험자 또는 최근2년내 피부과 미용시술 미경험자 좌담회/ 만30-49세 여성(전업주부 또는 풀타임 회사원)\n=============================\n★컨택시 현사용 화장품 제품명, 시술명 등 미리 확인합니다.\n▶공통조건\n1) 최근 6개월 내 피부과 시술경험자(얼굴 미용 목적) 또는 최근 2년 내 피부과 시술 미경험자\n2) 온라인 채널, 올리브영(온/오프)을 포함한 다양한 채널에서 스킨케어(기초화장품) 제품 구매자\n**반영구/단순 피부 마사지, 질병 치료 목적/다이어트 지방흡입은 미용시술에서 제외\n-------------------------------------------------------------------\n▶진행일정 (여의도역 부근 회사진행)\nG1.30대 전업주부--최근 6개월 내 피부과병원 미용시술 경험자--9/9(수) 오전 11시~오후 1시\nG2.30대 Full-time 직장인--최근 6개월 내 피부과병원 미용시술 경험자--9/14(월) 저녁 7시~저녁 9시\nG3.40대 전업주부--최근 6개월 내 피부과병원 미용시술 경험자--9/11(금) 오전 11시~오후 1시\nG4.40대 Full-time 직장인--최근 6개월 내 피부과병원 미용시술 경험자--9/14(월) 오전 11시~오후1시\nG5.30대 전업주부--최근 2년 내 피부과병원 미용시술 미경험자--9/10(목) 오전 11시~오후 1시\nG6.30대 Full-time 직장인--최근 2년 내 피부과병원 미용시술 미경험자--9/14(월) 오후 3시~오후 5시\nG7.40대 전업주부--최근 2년 내 피부과병원 미용시술 미경험자--9/11(금) 오후 3시~오후 5시\nG8.40대 Full-time 직장인--최근 2년 내 피부과병원 미용시술 미경험자--9/11(금) 저녁 7시~저녁 9시\n-------------------------------------------------------------------\n▶진행과정\n** 1단계 대상자 컨택통화(15-20분) → 2단계 참여확정통화 → 3단계 당일 최종 참석 **\n▶참석사례비 : 70,000원\n**최종 참여한 경우만, 좌담회 참여 이후 일관 본인 계좌이체 지급예정이며 소득신고를 위한 개인정보 입력이 필수입니다.\n-------------------------------------------------------------------\n▶기재 사항\n1. 성함\n2. 연락처\n3. 성별\n4. 연령(생년월일)\n5. 거주지(구, 동까지)\n6. 직업(풀타임 직장인(회사명/부서명), 전업주부 등 자세히) <풀타임 직장인 또는 전업주부 대상>\n7. 최근 1년 내 스킨케어 제품 구매 장소/채널 3곳은? <온/오프라인 모두 포함>\n8. 아래 본인에게 해당되는 시술경험 문장을 1가지 선택해주세요. <★중요>\n①지금까지 피부미용시술 받은 적 전혀 없음\n②예전에는 있지만 최근 2년 내에는 피부미용시술 받은 적 전혀 없음\n③최근 1년내 피부미용시술 받은 적 있음\n④최근 6개월 내 피부미용시술 받은 적 있음\n9. 현재 사용하는 화장품의 브랜드를 정확히 적어주세요(현재 미사용 제품은 ' X '표시).\n①스킨토너:\n②로션:\n③크림:\n④아이크림:\n⑤세럼/에센스/앰플:\n⑥마스크팩:\n⑦선제품(선크림/선스틱):\n10. <최근 6개월 내 시술경험자만 기입>최근 6개월 내 피부과/성형외과 병/의원에서 받은 시술의 종류를 모두 적어주세요\nEX) IPL, 프락셀, 레블라이트, V빔, 아쿠아필, 블랙필, 비타민 주사, 백옥주사, 울쎄라, 슈링크, 써마지, 인모드, 보톡스, 쥬베룩, 리쥬란 힐러, 필러, 윤곽주사, HPL 등\n11. 위에 본인에게 해당하는 진행 일정을 최종 확인하셨나요?\n★조사 대",
