      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n9/12) 경기지역 거주하는 20~39세 청년 남성 대상 평화.통일정책 토론회(4차)\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.02. 16:40\n조회 24\n구독\n9/12) 경기지역 거주하는 20~39세 청년 대상 평화.통일정책 토론회(4차)\n만 19~39세 경기지역 거주하는 청년들을 대상으로 평화.통일 정책 토론회를 진행할 예정입니다.\n** 경기지역에 거주하는 청년 대상입니다.\n1. 조사대상 : 만 19~39세 남녀\n2. 토론회 주제 : 평화·통일 쟁점 관련 전문가 발제 및 균형 정보 학습\n인식 공유, 쟁점 탐색, 이해관 재구성 등 분임 토론 참여\n3. 토론회 일정 : 9/12(토) 13시~17시\n4. 장소 : 수원경기아트센터 도움관 2층 컨벤션홀\n5. 사례비 : 6만원 cj상품권 현장지급\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\n6. 신청양식 : https://kstat.surveys.kr/2026/P26051103C/index.asp?ResType=85D53C4AFCIN081\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\n- 신청링크에는 토론회관련 내용과 함께 생년월일/ 성별/ 거주지역/ 이념성향/ 직업/ 신청자이름/ 연락처/ 이메일주소/ 소개자 작성으로 되어있습니다.\n(*신청링크 마지막에 소개자 입력 란이 생성되어 있습니다)\n존재하지 않는 이미지입니다.\n링크 통해 신청해주시는 분들은 순차적으로 안내 전화 드릴 예정입니다.\n** 해당 일자에 참여 가능한 신청자만 신청할 수 있도록 당부 부탁드립니다.\n** 해당 토론회는 일반 소규모의 좌담회와 달리 많은 인원이 참석하는 토론회입니다.\n좋아요\n0\n송파구 이웃은 지금 어떤 이야기 중일까?\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n9/12) 경기지역 거주하는 20~39세 청년 여성 대상 평화.통일정책 토론회(4차)\n좌담회알바좌담회카페\n26.09.02.\n댓글\n0\n9/12) 경기지역 거주하는 20~39세 청년 남성 대상 평화.통일정책 토론회(4차)\n좌담회알바좌담회카페\n26.09.02.\n댓글\n0\n만 16~44세 기혼여성- 패션관련 온라인 조사\n좌담회알바좌담회카페\n26.09.02.\n댓글\n0\n만 16~44세 미혼여성- 패션관련 온라인 조사\n좌담회알바좌담회카페\n26.09.02.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
