      "id": "bd28675a83fa01617dee472641b8a795",
      "title": "[비대면] 섬유유연제 사용 조사-만20~29세 1인가구 여성 9/1~약 2주[3만5천원]",
      "source": "researchi",
      "source_url": "https://researchi.co.kr/27810",
      "target_age": "만20~29세",
      "target_gender": "여성",
      "target_condition": "만20~29세 기혼 여성 (20대는 1인가구 미혼 가능)",
      "date": "중 정해진 가이드에 따라 성실히 참여 해주실 분",
      "time": "온라인 설문 각 차수별 10분",
      "duration": "조사 응답후 제품 발송해 주셔야 최종 완료",
      "reward": "지급하지 않습니다 )",
      "location": "확인 가능하도록, 전체샷+ 제품 확대샷, 최소 2장이상)을 아래 링크에 올려주신 분들 우선적으로 연락 드리겠습니다",
      "type": "온라인",
      "raw_content": "[비대면] 섬유유연제 사용 조사-만20~29세 1인가구 여성 9/1~약 2주[3만5천원]\n​\n섬유유연제 유치조사_ 스O글 허거블 코튼, 허거블 선샤인 사용자....추가로 모집\n​\n대상 : 만20~29세 기혼 여성 (20대는 1인가구 미혼 가능)\n댁 내 생활용품 구매 결정자\n조사 일정중 정해진 가이드에 따라 성실히 참여 해주실 분\n임신/수유중, 알러지, 호흡기 질환자는 참여 불가\n9월1~20일 여행,출장등 집을 비우는 계획이 없으신 분\n현재 20~29세 1인가구\n스O글 허O블 코튼, 허거블 선샤인 주 사용자\n일정 : 9월1일~약 2주간, 보내 드리는 섬유유연제를 사용후 온라인 설문 참여\n방법 : 제품을 댁으로 발송해 드림\n정해진 가이드에 따라 제품 사용후 총 3번의 온라인 설문 ( 온라인 설문은 각 차수별 10분 소요)\n조사 응답후 제품 발송해 주셔야 최종 완료\n( 회수가 되지 않거나, 분실시 사례비 지급하지 않습니다 )\n소요시간 : 온라인 설문 각 차수별 10분\n사례비 : 3만5천원 ( 사용 후 제품 선불 발송비 포함)\n안내사항\n신청후 섬유 유연제 사진 (섬유유연제가 놓여진 장소 확인 가능하도록, 전체샷+ 제품 확대샷, 최소 2장이상)을 아래 링크에 올려주신 분들 우선적으로 연락 드리겠습니다\n신청 시 소개자명\n\"하진혁\"\n을 반드시 기입해주세요.\n​\n신청하기",
